				[ 'p', 'É preciso a licença de Santa Cruz, tirada online no portal oficial. Para um estrangeiro não residente em 2026/27: <strong>$ 90.000 por um dia, $ 300.000 por uma semana e $ 450.000 pela temporada</strong> (cerca de US$ 58, US$ 194 e US$ 291 com US$ 1 = $ 1.545, de 8 de novembro de 2026). Valores do portal oficial, lidos em 4 de novembro de 2026.' ],
				[ 'h', 'Quanto custa uma saída com guia' ],
				[ 'p', 'Uma agência de El Calafate publica <strong>$ 440.000 o meio dia (5 horas) e $ 720.000 o dia inteiro (9 horas)</strong> por pescador, em 5 de novembro de 2026. Um operador publica em uma plataforma de reservas o dia de pesca a <strong>US$ 340 por adulto</strong> (11 de novembro de 2026), com a licença, o equipamento, o seguro e o traslado desde o hotel incluídos. Segundo esse operador pesca-se caminhando na água, nunca de barco, a temporada vai de novembro a abril e as capturas típicas pesam entre 500 gramas e 2 quilos.' ],
				[ 'pe', 'as regras do Parque Nacional Los Glaciares; o lago Roca, o rio Rico e o Pelque, que um operador cita e não constam no anexo que lemos; calendário por mês com uma fonte técnica; como chegar; foto com crédito.' ],
			],
			'faqs' => [ [ 'Quando se pode pescar perto de El Calafate?', 'O lago Argentino e o rio Santa Cruz estão liberados o ano todo. La Leona, o arroio Calafate e o rio Bote abrem em 1.º de outubro de 2026 e fecham em 3 de maio de 2027, segundo o Anexo I do regulamento de Santa Cruz.' ], [ 'De que licença preciso e quanto custa?', 'A licença de Santa Cruz. Para um estrangeiro não residente em 2026/27: $ 90.000 por um dia, $ 300.000 por uma semana e $ 450.000 pela temporada, segundo o portal oficial lido em 4 de novembro de 2026.' ], [ 'Posso ficar com os peixes?', 'Depende do ambiente. No lago Argentino, dois exemplares por dia. No arroio Calafate e no rio Bote, soltura obrigatória. Em La Leona, um salmão chinook por dia e o resto é solto.' ], [ 'Com o que se pode pescar?', 'Com uma única isca artificial com um único anzol simples ou duplo, com ou sem farpa. No rio Santa Cruz não se permite isca natural (salvo exceções) nem lastro de chumbo.' ], [ 'Quanto custa uma saída com guia?', 'Uma agência publica $ 440.000 o meio dia e $ 720.000 o dia inteiro por pescador (5 de novembro de 2026). Um operador publica US$ 340 por adulto com licença, equipamento e traslado incluídos (11 de novembro de 2026).' ], [ 'É preciso desinfetar o equipamento?', 'Sim no rio Santa Cruz, bacia afetada pelo Didymo: a desinfecção é obrigatória antes de passar a outro ambiente. Em La Leona é preciso desinfetar e lavar o equipamento ao fim do dia.' ] ],
			'fuentes' => [ [ 'Regulamento Geral de Pesca Esportiva da Província de Santa Cruz, temporada 2026/2027, e Anexo I de ambientes (lido por completo)', $sc, 1 ], [ 'Governo de Santa Cruz, Pesca e Aquicultura: valores das licenças 2026/2027 (portal oficial, lido em 4/11/2026)', $scv, 1 ], [ 'Pesquisa própria a partir de dados públicos e fornecedores associados: preços de saídas em 5 e 11 de novembro de 2026', '', 0 ] ],
			'paq' => [ 'titulo' => 'SALUM Tour & Travel: dia de pesca caminhando na água perto de El Calafate', 'resumen' => 'Saída em grupo reduzido a partir de El Calafate, com os dados que o operador publica em plataformas de reserva (11 de novembro de 2026); o site dele não foi lido. O guia escolhe o rio ou o lago naquela manhã. A Pescamapa não confirmou disponibilidade nem condições com o operador. Se você é o operador e algo mudou, escreva para nós e corrigimos ou tiramos.', 'mod' => 'Mosca ou spinning, caminhando na água', 'dur' => 'Dia inteiro de 9 horas; meio dia de 5 horas', 'cap' => 'Grupo reduzido: 3 ou 4 pescadores por guia, conforme a plataforma', 'incl' => [ 'Traslado desde o hotel', 'Guia de pesca', 'Equipamento (waders, botas, varas, carretilhas, moscas e iscas)', 'Licença de pesca', 'Seguro', 'Almoço ao ar livre (só no dia inteiro)' ], 'no' => [ 'Gorjetas' ], 'var' => [ 'Em outra plataforma: € 264 por pessoa (11/11/2026)' ], 'monto' => 340, 'moneda' => 'USD', 'unidad' => 'por adulto, dia de pesca' ],
		],
	],
	'ushuaia' => [
		'comun' => [ 'reglamento_autoridad' => 'Secretaría de Ambiente de Tierra del Fuego (Ministerio de Producción y Ambiente)', 'reglamento_url' => $tdfp ],
		'geo'   => [ 'region' => 'patagonia', 'provincia' => 'tierra-del-fuego', 'lat' => -54.80, 'lon' => -68.30, 'especies' => [ 'trucha' ] ],
		'es' => [
			'titulo' => 'Ushuaia (Tierra del Fuego)', 'slug' => 'pesca-en-ushuaia',
			'h1' => 'Pesca en Ushuaia, Tierra del Fuego: reglas, permiso y salidas 2026/27',
			'bajada' => 'Truchas en los ríos, lagunas y lagos del sur de Tierra del Fuego. Las reglas 2026/27 leídas de la resolución oficial, el permiso, lo que cuesta una salida con guía y lo que falta leer.',
			'modalidades' => "Mosca\nSpinning", 'epoca' => 'Del 30 de octubre de 2026 al 2 de mayo de 2027; desde el 1 de marzo de 2027, devolución obligatoria en toda la provincia.',
			'seo_title' => 'Pesca en Ushuaia, Tierra del Fuego: reglas y permiso', 'seo_description' => 'Guía de pesca en Ushuaia: temporada y reglas 2026/27 de Tierra del Fuego, lago Fagnano y lagunas, valores del permiso y precio de una salida con guía.',
			'resumen' => 'Resolución S.A. 259/2026 de la Secretaría de Ambiente de Tierra del Fuego, leída completa. La temporada 2026/27 va del 30/10/2026 al 2/5/2027. Desde el 1/3/2027 la devolución es obligatoria en toda la provincia. Fuera de los ambientes con regla propia se puede sacrificar un ejemplar por día. Solo se permiten spinning y mosca, con un señuelo artificial con un único anzuelo simple o doble; el trolling está prohibido.',
			'temporada' => [ [ '30 de octubre', 'Abre la temporada 2026/27 en Tierra del Fuego.' ], [ '1 de enero', 'Se habilitan el río Palacios y los ríos Milna, Tuerto, Turbio y el arroyo Subiabre, con devolución obligatoria.' ], [ '1 de marzo', 'Devolución obligatoria en todos los ambientes de la provincia, hasta el cierre.' ], [ '2 de mayo', 'Cierra la temporada (2027); después rige la veda.' ] ],
			'aguas' => [ [ 'Lago Fagnano', 'Zona preferencial: lleva un permiso adicional.' ], [ 'Río Olivia, río Pipo y arroyo Grande', 'Zonas de práctica de lanzamiento, de acceso gratuito, con permiso y devolución obligatoria.' ], [ 'Lagunas Negra, Margarita y Tres Marías', 'Devolución obligatoria; sin motor a explosión.' ] ],
			'cuerpo' => [
				[ 'p', '<strong>Ushuaia</strong> es la base para pescar truchas en los ríos, lagunas y lagos del sur de <strong>Tierra del Fuego</strong>, con el <strong>lago Fagnano</strong> como el ambiente más grande. Esta página reúne la temporada y las reglas 2026/27 leídas de la resolución oficial, el permiso, lo que cuesta una salida con guía y lo que todavía no leímos. La trucha de mar del río Grande tiene su propia guía.' ],
				[ 'h', 'La temporada y las reglas generales 2026/27' ],
				[ 'l', [ '<strong>Temporada:</strong> del 30 de octubre de 2026 al 2 de mayo de 2027, inclusive. Después rige la veda en toda la provincia.', '<strong>Devolución obligatoria</strong> en todos los ambientes desde el 1 de marzo de 2027 hasta el cierre.', '<strong>Cupo:</strong> fuera de los ambientes con regla propia, no más de un ejemplar por día.', '<strong>Modalidades:</strong> solo spinning (cuchara) y mosca, con un solo señuelo artificial con un único anzuelo simple o doble. En spinning se permite la boya tipo buldo con mosca.', '<strong>Prohibido:</strong> el trolling desde una embarcación a motor, la carnada, el lastre y los señuelos con pilas o baterías.' ] ],
				[ 'h', 'Reglas por ambiente cerca de Ushuaia' ],
				[ 'l', [ '<strong>Lago Fagnano:</strong> es zona preferencial y lleva un permiso adicional (abajo).', '<strong>Río Olivia, río Pipo y arroyo Grande:</strong> zonas para clínicas y práctica de lanzamiento, de acceso gratuito, con el permiso de pesca encima y devolución obligatoria.', '<strong>Río Palacios:</strong> se habilita el 1 de enero de 2027, con devolución obligatoria.', '<strong>Ríos Milna, Tuerto y Turbio y arroyo Subiabre:</strong> desde el 1 de enero de 2027, solo con devolución obligatoria.', '<strong>Laguna Negra:</strong> devolución obligatoria; prohibida la navegación a motor.', '<strong>Lagunas Margarita y Tres Marías:</strong> devolución obligatoria; sin motor a explosión.', '<strong>Río Valdez:</strong> devolución obligatoria desde el puente de la Ruta Nacional 3 aguas arriba; del puente a la desembocadura en el Fagnano está prohibido pescar todo el año.' ] ],
				[ 'h', 'El permiso y cuánto cuesta' ],
				[ 'p', 'Para un extranjero no residente, el permiso ordinario 2026/27 cuesta <strong>$ 78.000 por un día, $ 117.000 por tres días, $ 195.000 por una semana y $ 260.000 por la temporada</strong> (unos US$ 50, US$ 76, US$ 126 y US$ 168 con US$ 1 = $ 1.545, del 8 de noviembre de 2026). El lago Fagnano y los ríos Ewan Sur e Irigoyen son zona preferencial: suman un permiso adicional de <strong>$ 43.000 por un día, $ 85.000 por tres días, $ 130.000 por una semana o $ 247.000 por la temporada</strong>; para extranjeros de países limítrofes, $ 35.000, $ 62.000, $ 98.000 y $ 169.000. Valores de la Resolución 259/2026.' ],
				[ 'h', 'Cuánto cuesta una salida con guía' ],
				[ 'p', 'El único precio publicado que encontramos es el de un guía en una plataforma de reservas: <strong>€ 851 por persona</strong> por un día completo de 12 horas desde Ushuaia (11 de noviembre de 2026), con transporte, guía, licencia, equipo y refrigerios incluidos. Según ese guía se pesca en ríos, lagunas y lagos en el mismo día, con truchas de 1 a 4 kilos.' ],
				[ 'pe', 'las reglas del Parque Nacional Tierra del Fuego; más precios de guías de Ushuaia en su propio sitio; calendario por mes con una fuente técnica; cómo llegar a cada ambiente; foto con su crédito.' ],
			],
			'faqs' => [ [ '¿Cuándo se puede pescar en Ushuaia?', 'Del 30 de octubre de 2026 al 2 de mayo de 2027, según la Resolución 259/2026 de Tierra del Fuego. Desde el 1 de marzo de 2027 la devolución es obligatoria en todos los ambientes de la provincia.' ], [ '¿Qué permiso necesito y cuánto cuesta?', 'El permiso de Tierra del Fuego. Para un extranjero no residente en 2026/27: $ 78.000 por un día, $ 117.000 por tres días, $ 195.000 por una semana y $ 260.000 por la temporada. El lago Fagnano suma un permiso adicional desde $ 43.000 por día.' ], [ '¿Puedo quedarme con los peces?', 'Fuera de los ambientes con regla propia, un ejemplar por día hasta el 28 de febrero de 2027. Desde el 1 de marzo la devolución es obligatoria en toda la provincia, y muchos ambientes son de devolución toda la temporada.' ], [ '¿Se puede pescar al trolling?', 'No. La resolución prohíbe el trolling desde una embarcación a motor, y sanciona al pescador y al conductor. Solo se permiten spinning y mosca, con un señuelo artificial con un único anzuelo simple o doble.' ], [ '¿Cuánto cuesta una salida con guía?', 'El único precio publicado que encontramos: € 851 por persona por un día completo de 12 horas, con transporte, guía, licencia y equipo incluidos (plataforma de reservas, 11 de noviembre de 2026).' ], [ '¿Hay lugares para practicar gratis?', 'Sí: el río Olivia, el río Pipo y el arroyo Grande son zonas para clínicas y práctica de lanzamiento, de acceso gratuito. Hay que llevar el permiso de pesca y devolver todo.' ] ],
			'fuentes' => [ [ 'Resolución S.A. N.º 259/2026 de la Secretaría de Ambiente de Tierra del Fuego: reglamento, permisos y valores de la temporada 2026/27 (PDF oficial, leído completo)', $tdf, 1 ], [ 'Ministerio de Producción y Ambiente de Tierra del Fuego: pesca deportiva, temporada 2026-2027 (página oficial)', $tdfp, 1 ], [ 'Investigación propia a partir de datos públicos y proveedores asociados: precio de una salida al 11 de noviembre de 2026', '', 0 ] ],
			'paq' => [ 'titulo' => 'Ezequiel Navarro: día completo de pesca de truchas desde Ushuaia', 'resumen' => 'Salida de un día completo desde Ushuaia por ríos, lagunas y lagos, con los datos que el guía publica en una plataforma de reservas (11 de noviembre de 2026); no leímos un sitio propio. Pescamapa no confirmó disponibilidad ni condiciones con el guía. Si sos el guía y algo cambió, escribinos y lo corregimos o lo sacamos.', 'mod' => 'Pesca de truchas con guía, para todos los niveles', 'dur' => '12 horas', 'cap' => '', 'incl' => [ 'Transporte de ida y vuelta', 'Guía de pesca', 'Licencia de pesca', 'Equipo de pesca (si no llevás el tuyo)', 'Refrigerios' ], 'no' => [], 'var' => [], 'monto' => 851, 'moneda' => 'EUR', 'unidad' => 'por persona, día completo' ],
		],
		'en' => [
			'titulo' => 'Ushuaia (Tierra del Fuego)', 'slug' => 'fishing-in-ushuaia',
			'h1' => 'Fishing in Ushuaia, Tierra del Fuego: rules, permit and day trips 2026/27',
			'bajada' => 'Trout in the rivers, lagoons and lakes of southern Tierra del Fuego. The 2026/27 rules read from the official resolution, the permit, what a guided day costs and what is still to read.',
			'modalidades' => "Fly fishing\nSpinning", 'epoca' => '30 October 2026 to 2 May 2027; from 1 March 2027, mandatory release across the province.',
			'seo_title' => 'Fishing in Ushuaia, Tierra del Fuego: rules and permit', 'seo_description' => 'Fishing guide to Ushuaia: Tierra del Fuego 2026/27 season and rules, Lago Fagnano and lagoons, permit prices and what a guided day costs.',
			'resumen' => 'Resolución S.A. 259/2026 of the Tierra del Fuego Environment Secretariat, read in full. The 2026/27 season runs from 30 October 2026 to 2 May 2027. From 1 March 2027 release is mandatory across the province. Outside waters with their own rule one fish a day may be kept. Only spinning and fly are allowed, with one artificial lure with one single or double hook; trolling is banned.',
			'temporada' => [ [ '30 October', 'The 2026/27 season opens in Tierra del Fuego.' ], [ '1 January', 'The Palacios River and the Milna, Tuerto and Turbio rivers and Subiabre stream open, with mandatory release.' ], [ '1 March', 'Mandatory release on every water in the province, until the close.' ], [ '2 May', 'The season closes (2027); the closed season follows.' ] ],
			'aguas' => [ [ 'Lago Fagnano', 'Preferential zone: needs an additional permit.' ], [ 'Olivia River, Pipo River and Grande stream', 'Casting practice zones, free access, permit required, mandatory release.' ], [ 'Negra, Margarita and Tres Marías lagoons', 'Mandatory release; no combustion engines.' ] ],
			'cuerpo' => [
				[ 'p', '<strong>Ushuaia</strong> is the base for trout fishing in the rivers, lagoons and lakes of southern <strong>Tierra del Fuego</strong>, with <strong>Lago Fagnano</strong> as the largest water. This page gathers the 2026/27 season and rules read from the official resolution, the permit, what a guided day costs and what we have not read yet. The sea-run brown trout of the Río Grande has its own guide.' ],
				[ 'h', 'The 2026/27 season and general rules' ],
				[ 'l', [ '<strong>Season:</strong> 30 October 2026 to 2 May 2027, inclusive. After that the whole province is closed.', '<strong>Mandatory release</strong> on every water from 1 March 2027 until the close.', '<strong>Bag limit:</strong> outside waters with their own rule, no more than one fish a day.', '<strong>Methods:</strong> only spinning (spoon) and fly, with one artificial lure with one single or double hook. With spinning gear a bubble float with a fly is allowed.', '<strong>Banned:</strong> trolling from a motor boat, bait, weights, and lures with batteries.' ] ],
				[ 'h', 'Rules by water near Ushuaia' ],
				[ 'l', [ '<strong>Lago Fagnano:</strong> a preferential zone that needs an additional permit (below).', '<strong>Olivia River, Pipo River and Grande stream:</strong> zones for casting clinics and practice, free access, carrying the fishing permit, with mandatory release.', '<strong>Palacios River:</strong> opens on 1 January 2027, with mandatory release.', '<strong>Milna, Tuerto and Turbio rivers and Subiabre stream:</strong> from 1 January 2027, mandatory release only.', '<strong>Laguna Negra:</strong> mandatory release; motor boats are banned.', '<strong>Margarita and Tres Marías lagoons:</strong> mandatory release; no combustion engines.', '<strong>Valdez River:</strong> mandatory release from the National Route 3 bridge upstream; from the bridge to its mouth on Lago Fagnano fishing is banned all year.' ] ],
				[ 'h', 'The permit and what it costs' ],
				[ 'p', 'For a non-resident foreigner, the ordinary 2026/27 permit costs <strong>$ 78,000 for one day, $ 117,000 for three days, $ 195,000 for a week and $ 260,000 for the season</strong> (about US$ 50, US$ 76, US$ 126 and US$ 168 at US$ 1 = $ 1,545, as of 8 November 2026). Lago Fagnano and the Ewan Sur and Irigoyen rivers are a preferential zone: they add a permit of <strong>$ 43,000 for one day, $ 85,000 for three days, $ 130,000 for a week or $ 247,000 for the season</strong>; for foreigners from neighbouring countries, $ 35,000, $ 62,000, $ 98,000 and $ 169,000. Values from Resolución 259/2026.' ],
				[ 'h', 'What a guided day costs' ],
				[ 'p', 'The only published price we found is a guide\'s listing on a booking platform: <strong>€ 851 per person</strong> for a full day of 12 hours from Ushuaia (11 November 2026), with transport, guide, licence, gear and snacks included. According to that guide you fish rivers, lagoons and lakes in the same day, for trout of 1 to 4 kilos.' ],
				[ 'pe', 'the rules of Tierra del Fuego National Park; more prices from Ushuaia guides on their own sites; a month-by-month calendar with a technical source; how to reach each water; a photo with its credit.' ],
			],
			'faqs' => [ [ 'When can I fish in Ushuaia?', 'From 30 October 2026 to 2 May 2027, according to Resolución 259/2026 of Tierra del Fuego. From 1 March 2027 release is mandatory on every water in the province.' ], [ 'Which permit do I need and how much is it?', 'The Tierra del Fuego permit. For a non-resident foreigner in 2026/27: $ 78,000 for one day, $ 117,000 for three days, $ 195,000 for a week and $ 260,000 for the season. Lago Fagnano adds a permit from $ 43,000 a day.' ], [ 'Can I keep fish?', 'Outside waters with their own rule, one fish a day until 28 February 2027. From 1 March release is mandatory across the province, and many waters are release-only all season.' ], [ 'Is trolling allowed?', 'No. The resolution bans trolling from a motor boat, and penalises both the angler and the skipper. Only spinning and fly are allowed, with one artificial lure with one single or double hook.' ], [ 'How much does a guided day cost?', 'The only published price we found: € 851 per person for a full day of 12 hours, with transport, guide, licence and gear included (booking platform, 11 November 2026).' ], [ 'Is there anywhere to practise for free?', 'Yes: the Olivia River, the Pipo River and the Grande stream are zones for casting clinics and practice, with free access. You must carry the fishing permit and release everything.' ] ],
			'fuentes' => [ [ 'Resolución S.A. No. 259/2026 of the Tierra del Fuego Environment Secretariat: regulation, permits and values for the 2026/27 season (official PDF, read in full)', $tdf, 1 ], [ 'Tierra del Fuego Ministry of Production and Environment: sport fishing, 2026-2027 season (official page)', $tdfp, 1 ], [ 'Our own research based on public data and partner providers: trip price as of 11 November 2026', '', 0 ] ],
			'paq' => [ 'titulo' => 'Ezequiel Navarro: full-day trout fishing from Ushuaia', 'resumen' => 'Full-day trip from Ushuaia to rivers, lagoons and lakes, using what the guide publishes on a booking platform (11 November 2026); we did not read a website of his own. Pescamapa has not confirmed availability or terms with the guide. If you are the guide and something has changed, write to us and we will correct it or take it down.', 'mod' => 'Guided trout fishing, all levels', 'dur' => '12 hours', 'cap' => '', 'incl' => [ 'Round-trip transport', 'Fishing guide', 'Fishing licence', 'Fishing gear (if you do not bring your own)', 'Snacks' ], 'no' => [], 'var' => [], 'monto' => 851, 'moneda' => 'EUR', 'unidad' => 'per person, full day' ],
		],
		'pt' => [
			'titulo' => 'Ushuaia (Terra do Fogo)', 'slug' => 'pesca-em-ushuaia',
			'h1' => 'Pesca em Ushuaia, Terra do Fogo: regras, licença e saídas 2026/27',
			'bajada' => 'Trutas nos rios, lagoas e lagos do sul da Terra do Fogo. As regras 2026/27 lidas da resolução oficial, a licença, quanto custa uma saída com guia e o que falta ler.',
			'modalidades' => "Mosca\nSpinning", 'epoca' => 'De 30 de outubro de 2026 a 2 de maio de 2027; a partir de 1.º de março de 2027, soltura obrigatória em toda a província.',
			'seo_title' => 'Pesca em Ushuaia, Terra do Fogo: regras e licença', 'seo_description' => 'Guia de pesca em Ushuaia: temporada e regras 2026/27 da Terra do Fogo, lago Fagnano e lagoas, valores da licença e preço de uma saída com guia.',
			'resumen' => 'Resolução S.A. 259/2026 da Secretaria de Ambiente da Terra do Fogo, lida por completo. A temporada 2026/27 vai de 30/10/2026 a 2/5/2027. A partir de 1/3/2027 a soltura é obrigatória em toda a província. Fora dos ambientes com regra própria pode-se abater um exemplar por dia. Só se permitem spinning e mosca, com uma isca artificial com um único anzol simples ou duplo; o trolling é proibido.',
			'temporada' => [ [ '30 de outubro', 'Abre a temporada 2026/27 na Terra do Fogo.' ], [ '1.º de janeiro', 'Liberam-se o rio Palacios e os rios Milna, Tuerto, Turbio e o arroio Subiabre, com soltura obrigatória.' ], [ '1.º de março', 'Soltura obrigatória em todos os ambientes da província, até o fechamento.' ], [ '2 de maio', 'Fecha a temporada (2027); depois vale o defeso.' ] ],
			'aguas' => [ [ 'Lago Fagnano', 'Zona preferencial: exige uma licença adicional.' ], [ 'Rio Olivia, rio Pipo e arroio Grande', 'Zonas de prática de arremesso, de acesso gratuito, com licença e soltura obrigatória.' ], [ 'Lagoas Negra, Margarita e Tres Marías', 'Soltura obrigatória; sem motor a combustão.' ] ],
			'cuerpo' => [
				[ 'p', '<strong>Ushuaia</strong> é a base para pescar trutas nos rios, lagoas e lagos do sul da <strong>Terra do Fogo</strong>, com o <strong>lago Fagnano</strong> como o maior ambiente. Esta página reúne a temporada e as regras 2026/27 lidas da resolução oficial, a licença, quanto custa uma saída com guia e o que ainda não lemos. A truta do mar do rio Grande tem seu próprio guia.' ],
				[ 'h', 'A temporada e as regras gerais 2026/27' ],
				[ 'l', [ '<strong>Temporada:</strong> de 30 de outubro de 2026 a 2 de maio de 2027, inclusive. Depois vale o defeso em toda a província.', '<strong>Soltura obrigatória</strong> em todos os ambientes de 1.º de março de 2027 até o fechamento.', '<strong>Cota:</strong> fora dos ambientes com regra própria, não mais de um exemplar por dia.', '<strong>Modalidades:</strong> só spinning (colher) e mosca, com uma única isca artificial com um único anzol simples ou duplo. No spinning permite-se a boia tipo buldo com mosca.', '<strong>Proibido:</strong> o trolling a partir de embarcação a motor, a isca natural, o lastro e as iscas com pilhas ou baterias.' ] ],
				[ 'h', 'Regras por ambiente perto de Ushuaia' ],
				[ 'l', [ '<strong>Lago Fagnano:</strong> é zona preferencial e exige uma licença adicional (abaixo).', '<strong>Rio Olivia, rio Pipo e arroio Grande:</strong> zonas para clínicas e prática de arremesso, de acesso gratuito, com a licença de pesca em mãos e soltura obrigatória.', '<strong>Rio Palacios:</strong> libera-se em 1.º de janeiro de 2027, com soltura obrigatória.', '<strong>Rios Milna, Tuerto e Turbio e arroio Subiabre:</strong> a partir de 1.º de janeiro de 2027, só com soltura obrigatória.', '<strong>Lagoa Negra:</strong> soltura obrigatória; proibida a navegação a motor.', '<strong>Lagoas Margarita e Tres Marías:</strong> soltura obrigatória; sem motor a combustão.', '<strong>Rio Valdez:</strong> soltura obrigatória da ponte da Rota Nacional 3 rio acima; da ponte até a desembocadura no Fagnano é proibido pescar o ano todo.' ] ],
				[ 'h', 'A licença e quanto custa' ],
				[ 'p', 'Para um estrangeiro não residente, a licença comum 2026/27 custa <strong>$ 78.000 por um dia, $ 117.000 por três dias, $ 195.000 por uma semana e $ 260.000 pela temporada</strong> (cerca de US$ 50, US$ 76, US$ 126 e US$ 168 com US$ 1 = $ 1.545, de 8 de novembro de 2026). O lago Fagnano e os rios Ewan Sur e Irigoyen são zona preferencial: somam uma licença adicional de <strong>$ 43.000 por um dia, $ 85.000 por três dias, $ 130.000 por uma semana ou $ 247.000 pela temporada</strong>; para estrangeiros de países limítrofes, como o Brasil, $ 35.000, $ 62.000, $ 98.000 e $ 169.000. Valores da Resolução 259/2026.' ],
				[ 'h', 'Quanto custa uma saída com guia' ],
				[ 'p', 'O único preço publicado que encontramos é o de um guia em uma plataforma de reservas: <strong>€ 851 por pessoa</strong> por um dia inteiro de 12 horas a partir de Ushuaia (11 de novembro de 2026), com transporte, guia, licença, equipamento e lanches incluídos. Segundo esse guia pesca-se em rios, lagoas e lagos no mesmo dia, com trutas de 1 a 4 quilos.' ],
				[ 'pe', 'as regras do Parque Nacional Tierra del Fuego; mais preços de guias de Ushuaia em seus próprios sites; calendário por mês com uma fonte técnica; como chegar a cada ambiente; foto com crédito.' ],
			],
			'faqs' => [ [ 'Quando se pode pescar em Ushuaia?', 'De 30 de outubro de 2026 a 2 de maio de 2027, segundo a Resolução 259/2026 da Terra do Fogo. A partir de 1.º de março de 2027 a soltura é obrigatória em todos os ambientes da província.' ], [ 'De que licença preciso e quanto custa?', 'A licença da Terra do Fogo. Para um estrangeiro não residente em 2026/27: $ 78.000 por um dia, $ 117.000 por três dias, $ 195.000 por uma semana e $ 260.000 pela temporada. O lago Fagnano soma uma licença adicional a partir de $ 43.000 por dia.' ], [ 'Posso ficar com os peixes?', 'Fora dos ambientes com regra própria, um exemplar por dia até 28 de fevereiro de 2027. A partir de 1.º de março a soltura é obrigatória em toda a província, e muitos ambientes são de soltura a temporada inteira.' ], [ 'Pode-se pescar de trolling?', 'Não. A resolução proíbe o trolling a partir de embarcação a motor e pune o pescador e o condutor. Só se permitem spinning e mosca, com uma isca artificial com um único anzol simples ou duplo.' ], [ 'Quanto custa uma saída com guia?', 'O único preço publicado que encontramos: € 851 por pessoa por um dia inteiro de 12 horas, com transporte, guia, licença e equipamento incluídos (plataforma de reservas, 11 de novembro de 2026).' ], [ 'Há lugares para praticar de graça?', 'Sim: o rio Olivia, o rio Pipo e o arroio Grande são zonas para clínicas e prática de arremesso, de acesso gratuito. É preciso levar a licença de pesca e soltar tudo.' ] ],
			'fuentes' => [ [ 'Resolução S.A. n.º 259/2026 da Secretaria de Ambiente da Terra do Fogo: regulamento, licenças e valores da temporada 2026/27 (PDF oficial, lido por completo)', $tdf, 1 ], [ 'Ministério de Produção e Ambiente da Terra do Fogo: pesca esportiva, temporada 2026-2027 (página oficial)', $tdfp, 1 ], [ 'Pesquisa própria a partir de dados públicos e fornecedores associados: preço de uma saída em 11 de novembro de 2026', '', 0 ] ],
			'paq' => [ 'titulo' => 'Ezequiel Navarro: dia inteiro de pesca de trutas a partir de Ushuaia', 'resumen' => 'Saída de um dia inteiro a partir de Ushuaia por rios, lagoas e lagos, com os dados que o guia publica em uma plataforma de reservas (11 de novembro de 2026); não lemos um site próprio. A Pescamapa não confirmou disponibilidade nem condições com o guia. Se você é o guia e algo mudou, escreva para nós e corrigimos ou tiramos.', 'mod' => 'Pesca de trutas com guia, para todos os níveis', 'dur' => '12 horas', 'cap' => '', 'incl' => [ 'Transporte de ida e volta', 'Guia de pesca', 'Licença de pesca', 'Equipamento de pesca (se não levar o seu)', 'Lanches' ], 'no' => [], 'var' => [], 'monto' => 851, 'moneda' => 'EUR', 'unidad' => 'por pessoa, dia inteiro' ],
		],
	],
];

$n = 0;
foreach ( $destinos as $clave => $d ) {
	foreach ( [ 'es', 'en', 'pt' ] as $i ) {
		$g  = $d[ $i ];
		$tl = mb_strlen( $g['seo_title'] );
		$dl = mb_strlen( $g['seo_description'] );
		if ( $tl > 60 || $dl > 160 || $dl < 70 ) {
			WP_CLI::error( "SEO fuera de rango $clave ($i): title $tl, description $dl" );
		}
		if ( pm_buscar( 'pm_destino', $clave, $i ) ) {
			WP_CLI::log( "$clave ($i) ya existe: no toco nada." );
			continue;
		}
		$cuerpo = implode( "\n\n", array_map( fn( $b ) => match ( $b[0] ) { 'p' => $P( $b[1] ), 'h' => $H( $b[1] ), 'l' => $L( $b[1] ), 'pe' => $PE( $b[1] ) }, $g['cuerpo'] ) );
		WP_CLI::log( ( $aplicar ? 'APLICA' : 'SIMULACRO' ) . ": $clave ($i) «{$g['titulo']}» /{$g['slug']}/ con " . count( $g['faqs'] ) . ' preguntas, ' . count( $g['fuentes'] ) . " fuentes y 1 paquete (title $tl / description $dl)" );
		$n++;
		if ( ! $aplicar ) {
			continue;
		}
		$id = wp_insert_post( [ 'post_type' => 'pm_destino', 'post_status' => 'publish', 'post_title' => $g['titulo'], 'post_name' => $g['slug'], 'post_content' => wp_slash( $cuerpo ) ], true );
		if ( is_wp_error( $id ) ) {
			WP_CLI::error( $id->get_error_message() );
		}
		$q      = $g['paq'];
		$campos = [
			'clave' => $clave, 'idioma' => $i, 'autor' => 'Equipo Pescamapa', 'actualizado' => $hoy, 'reglamento_verificado' => $hoy,
			'h1' => $g['h1'], 'bajada' => $g['bajada'], 'modalidades' => $g['modalidades'], 'epoca' => $g['epoca'],
			'seo_title' => $g['seo_title'], 'seo_description' => $g['seo_description'], 'reglamento_resumen' => $g['resumen'],
			'temporada' => array_map( fn( $t ) => [ 'meses' => $t[0], 'que' => $t[1] ], $g['temporada'] ),
			'aguas'     => array_map( fn( $a ) => [ 'nombre' => $a[0], 'nota' => $a[1], 'lat' => '', 'lon' => '' ], $g['aguas'] ),
			'faqs'      => array_map( fn( $f ) => [ 'pregunta' => $f[0], 'respuesta' => $f[1] ], $g['faqs'] ),
			'fuentes'   => $F( $g['fuentes'] ),
			'paquetes'  => [ [
				'publicado' => 1, 'titulo' => $q['titulo'], 'resumen' => $q['resumen'], 'modalidad' => $q['mod'], 'duracion' => $q['dur'], 'capacidad' => $q['cap'],
				'incluye' => implode( "\n", $q['incl'] ), 'no_incluye' => implode( "\n", $q['no'] ), 'variantes' => implode( "\n", $q['var'] ),
				'desde_monto' => $q['monto'], 'desde_moneda' => $q['moneda'], 'desde_unidad' => $q['unidad'], 'desde_fecha' => '2026-11-11', 'interno' => $int,
			] ],
		] + $d['comun'];
		if ( 'es' === $i ) {
			$campos += $d['geo'];
		}
		foreach ( $campos as $k => $v ) {
			update_field( $k, $v, $id );
		}
		update_post_meta( $id, 'es' === $i ? '_pm_es_editado' : '_pm_traducido', time() + ( 'es' === $i ? 0 : 1 ) );
		$ok = count( pm_filas( 'faqs', $id ) ) === count( $g['faqs'] ) && count( pm_filas( 'fuentes', $id ) ) === count( $g['fuentes'] ) && 1 === count( pm_filas( 'paquetes', $id ) );
		WP_CLI::log( ( $ok ? 'VERIFIED' : 'FALLÓ' ) . ": $clave ($i) #$id " . get_permalink( $id ) );
		$ok || WP_CLI::error( "$clave ($i): la lectura de vuelta no coincide." );
	}
}
if ( $aplicar ) {
	flush_rewrite_rules( false );
}
WP_CLI::success( ( $aplicar ? 'Aplicado' : 'Simulacro terminado' ) . ": $n guías." );
